using System.Linq;
using Autodesk.Revit.DB;
using Autodesk.Revit.DB.Structure;

var doc = Document;
// setup: a structural framing (beam) symbol and the lowest level
var symbol = new FilteredElementCollector(doc).OfCategory(BuiltInCategory.OST_StructuralFraming).OfClass(typeof(FamilySymbol)).Cast<FamilySymbol>().First();
var level  = new FilteredElementCollector(doc).OfClass(typeof(Level)).Cast<Level>().OrderBy(l => l.Elevation).First();
var line   = Line.CreateBound(new XYZ(0, 0, 0), new XYZ(20, 0, 0));

ElementId beamId = null;
// step 1: activate the symbol, then place the beam along the line as StructuralType.Beam
Connector.WithTransaction(doc, () => {
    if (!symbol.IsActive) symbol.Activate();
    var beam = doc.Create.NewFamilyInstance(line, symbol, level, StructuralType.Beam);
    beamId = beam.Id;
});

var created = (FamilyInstance)doc.GetElement(beamId);
return new { beamId = beamId.ToString(), symbol = symbol.Name, level = level.Name, structuralType = created.StructuralType.ToString(), category = created.Category?.Name };
